query IssueRepositoryInfo($owner: String!, $name: String!) {
	repository(owner: $owner, name: $name) {
		id
		databaseId
		name
		owner { login }
		hasIssuesEnabled
		viewerPermission
	}
}

mutation IssueCreate($input: CreateIssueInput!) {
	createIssue(input: $input) {
		issue {
			id
			url
		}
	}
}
